const now = new Date().toISOString();

return [{
  json: {
    mode: 'scheduled',
    host: 'mlab-test',
    timeframe: 'today',
    requestType: 'scheduled_monitoring',
    chatId: '6925837675',
    fromUser: 'system',
    originalRequest: 'Scheduled security monitoring check',
    attentionThreshold: 5,
    requestedAt: now
  }
}];

const raw = String($json.stdout || '');
const stderr = String($json.stderr || '');
const req = $item(0).$node['Normalize Scheduled Request'].json;

const clean = (text) =>
  text
    .split('\n')
    .map(v => v.replace(/\r/g, '').trim())
    .filter(Boolean);

const lines = clean(raw);
const knownUsers = ['employee1', 'employee2', 'employee3', 'intern1', 'contractor1'];

const perUserCounts = {};
const userCommands = {};

for (const user of knownUsers) {
  perUserCounts[user] = {
    status: 'OK',
    failed_sudo: 0,
    policy_warnings: 0,
    tmp_script_exec: 0,
    software_install: 0,
    persistence_attempt: 0,
    total_violations: 0
  };
  userCommands[user] = [];
}

let currentUser = null;

for (const line of lines) {
  if (line.startsWith('USER=')) {
    currentUser = line.split('=')[1]?.trim();
    continue;
  }

  if (currentUser && perUserCounts[currentUser]) {
    const [key, value] = line.split('=');

    if (key === 'status') perUserCounts[currentUser].status = value;
    if (key === 'failed_sudo') perUserCounts[currentUser].failed_sudo = Number(value) || 0;
    if (key === 'policy_warnings') perUserCounts[currentUser].policy_warnings = Number(value) || 0;
    if (key === 'tmp_script_exec') perUserCounts[currentUser].tmp_script_exec = Number(value) || 0;
    if (key === 'software_install') perUserCounts[currentUser].software_install = Number(value) || 0;
    if (key === 'persistence_attempt') perUserCounts[currentUser].persistence_attempt = Number(value) || 0;
    if (key === 'total_violations') perUserCounts[currentUser].total_violations = Number(value) || 0;
  }

  if (line.includes('COMPANY_POLICY_WARNING')) {
    const userMatch = line.match(/user=([a-zA-Z0-9_-]+)/);
    const cmdMatch = line.match(/command='([^']+)'/);

    if (userMatch && cmdMatch) {
      const user = userMatch[1];
      const cmd = cmdMatch[1];

      if (userCommands[user]) {
        userCommands[user].push(cmd);
      }
    }
  }
}

for (const user of Object.keys(userCommands)) {
  userCommands[user] = [...new Set(userCommands[user])];
}

const warnings = [];
const attentionUsers = [];
let totalPolicyViolations = 0;

for (const [user, data] of Object.entries(perUserCounts)) {
  totalPolicyViolations += data.total_violations;

  if (data.total_violations >= req.attentionThreshold || data.status === 'NEEDS_ATTENTION') {
    attentionUsers.push({
      user,
      count: data.total_violations,
      status: data.status,
      commands: userCommands[user]
    });
  } else if (data.total_violations > 0 || data.policy_warnings > 0) {
    warnings.push({
      user,
      count: data.total_violations,
      policy_warnings: data.policy_warnings,
      status: data.status,
      commands: userCommands[user]
    });
  }
}

return [{
  json: {
    ...req,
    perUserCounts,
    violationSummary: perUserCounts,
    warnings,
    attentionUsers,
    totalPolicyViolations,
    userCommands,
    alertNeeded: attentionUsers.length > 0,
    shouldAlertByRule: attentionUsers.length > 0,
    hasWarnings: warnings.length > 0,
    rawLineCount: lines.length,
    missingCollector: /script missing:/i.test(raw),
    stderr
  }
}];

const data = $json;

const host = data.host || 'mlab-test';
const timeframe = data.timeframe || 'today';
const total = Number(data.totalPolicyViolations || 0);
const attentionUsers = Array.isArray(data.attentionUsers) ? data.attentionUsers : [];
const warnings = Array.isArray(data.warnings) ? data.warnings : [];

function uniqueCommands(commands) {
  if (!Array.isArray(commands) || commands.length === 0) return [];
  return [...new Set(commands.filter(Boolean))];
}

function formatAttention(userObj) {
  const user = userObj.user || 'unknown user';
  const count = Number(userObj.count || 0);
  const commands = uniqueCommands(userObj.commands);

  if (commands.length === 0) {
    return `- ${user}: ${count} policy warnings, needs admin review.`;
  }

  return `- ${user}: ${count} policy warnings, needs admin review, tried to run: ${commands.join(', ')} ${count} times.`;
}

function formatWarning(userObj) {
  const user = userObj.user || 'unknown user';
  const count = Number(userObj.count || userObj.policy_warnings || 0);
  const commands = uniqueCommands(userObj.commands);

  if (commands.length === 0) {
    return `- ${user}: ${count} policy warnings, below the admin-review threshold.`;
  }

  return `- ${user}: ${count} policy warnings, below the admin-review threshold, tried to run: ${commands.join(', ')} ${count} times.`;
}

const attentionText = attentionUsers.length ? attentionUsers.map(formatAttention).join('\n') : '- None';
const warningText = warnings.length ? warnings.map(formatWarning).join('\n') : '- None';

const stoodOut = [];

if (attentionUsers.length > 0) {
  stoodOut.push(`${attentionUsers.length} user(s) crossed the admin-review threshold.`);
}

for (const userObj of attentionUsers.slice(0, 2)) {
  const commands = uniqueCommands(userObj.commands);
  stoodOut.push(`${userObj.user} reached ${userObj.count} policy warnings${commands.length ? ` after trying to run: ${commands.join(', ')}` : ''}.`);
}

for (const userObj of warnings.slice(0, 2)) {
  const commands = uniqueCommands(userObj.commands);
  stoodOut.push(`${userObj.user} has ${userObj.count || userObj.policy_warnings} policy warnings but is still below the admin-review threshold${commands.length ? ` after trying to run: ${commands.join(', ')}` : ''}.`);
}

if (stoodOut.length === 0) {
  stoodOut.push('No users crossed the admin-review threshold.');
}

const assessment = attentionUsers.length > 0
  ? 'This appears to be repeated policy-warning activity, not confirmed malware or compromise.'
  : warnings.length > 0
    ? 'This is warning-level policy activity and has not reached the admin-review threshold.'
    : 'No policy-warning activity was detected in this check.';

const recommendedAction = attentionUsers.length > 0
  ? `Review ${attentionUsers.map(u => u.user).join(', ')} activity and consider temporarily restricting the account(s) pending admin review.`
  : warnings.length > 0
    ? 'Continue monitoring these users and review activity if the warnings continue.'
    : 'Continue routine monitoring.';

const telegramMessage = [
  '🚨 AI Security Guard Alert',
  `Host: ${host}`,
  `Timeframe: ${timeframe}`,
  `Violation count: ${total}`,
  '',
  'Users needing attention:',
  attentionText,
  '',
  'Other warnings:',
  warningText,
  '',
  'What stood out:',
  ...stoodOut.slice(0, 4).map(line => `- ${line}`),
  '',
  'Assessment:',
  assessment,
  '',
  'Recommended action:',
  recommendedAction
].join('\n');

return [{
  json: {
    ...data,
    shouldSendTelegram: attentionUsers.length > 0,
    telegramMessage
  }
}];

const raw = String($json.stdout || '');
const stderr = String($json.stderr || '');

/**
 * Safely get request context from whichever upstream node exists.
 */
function getNodeJson(nodeName) {
  try {
    return $item(0).$node[nodeName].json;
  } catch (e) {
    return null;
  }
}

const req =
  getNodeJson('Parse AI Intent Output') ||
  getNodeJson('Normalize Telegram Request') ||
  getNodeJson('Normalize Report Request') ||
  $json ||
  {};

const clean = (text) =>
  text
    .split('\n')
    .map(v => v.replace(/\r/g, '').trim())
    .filter(Boolean);

const lines = clean(raw);

const knownUsers = [
  'employee1',
  'employee2',
  'employee3',
  'intern1',
  'contractor1'
];

const perUserCounts = {};
const userCommandsRaw = {};

for (const user of knownUsers) {
  perUserCounts[user] = {
    status: 'OK',
    failed_sudo: 0,
    policy_warnings: 0,
    sudo_commands: 0,
    tmp_script_exec: 0,
    software_install: 0,
    persistence_attempt: 0,
    total_violations: 0
  };

  userCommandsRaw[user] = [];
}

let currentUser = null;

for (const line of lines) {
  if (line.startsWith('USER=')) {
    currentUser = line.split('=')[1]?.trim();
    continue;
  }

  if (currentUser && perUserCounts[currentUser]) {
    const [key, value] = line.split('=');

    if (key === 'status') perUserCounts[currentUser].status = value;
    if (key === 'failed_sudo') perUserCounts[currentUser].failed_sudo = Number(value) || 0;
    if (key === 'policy_warnings') perUserCounts[currentUser].policy_warnings = Number(value) || 0;
    if (key === 'sudo_commands') perUserCounts[currentUser].sudo_commands = Number(value) || 0;
    if (key === 'tmp_script_exec') perUserCounts[currentUser].tmp_script_exec = Number(value) || 0;
    if (key === 'software_install') perUserCounts[currentUser].software_install = Number(value) || 0;
    if (key === 'persistence_attempt') perUserCounts[currentUser].persistence_attempt = Number(value) || 0;
    if (key === 'total_violations') perUserCounts[currentUser].total_violations = Number(value) || 0;
  }

  if (line.includes('COMPANY_POLICY_WARNING')) {
    const userMatch = line.match(/user=([a-zA-Z0-9_-]+)/);
    const cmdMatch = line.match(/command='([^']+)'/);

    if (userMatch && cmdMatch) {
      const user = userMatch[1];
      const cmd = cmdMatch[1];

      if (userCommandsRaw[user]) {
        userCommandsRaw[user].push(cmd);
      }
    }
  }
}

const userCommands = {};
for (const user of Object.keys(userCommandsRaw)) {
  userCommands[user] = [...new Set(userCommandsRaw[user])];
}

const warnings = [];
const attentionUsers = [];
let totalPolicyViolations = 0;

const threshold = Number(req.attentionThreshold || 5);

for (const [user, data] of Object.entries(perUserCounts)) {
  totalPolicyViolations += data.total_violations;

  if (data.total_violations >= threshold || data.status === 'NEEDS_ATTENTION') {
    attentionUsers.push({
      user,
      count: data.total_violations,
      status: data.status,
      commands: userCommands[user],
      policy_warnings: data.policy_warnings,
      software_install: data.software_install,
      failed_sudo: data.failed_sudo
    });
  } else if (data.total_violations > 0 || data.policy_warnings > 0) {
    warnings.push({
      user,
      count: data.total_violations,
      status: data.status,
      commands: userCommands[user],
      policy_warnings: data.policy_warnings,
      software_install: data.software_install,
      failed_sudo: data.failed_sudo
    });
  }
}

/**
 * Unknown requested user support.
 * Example: "employee4" should be detected even if AI/userFilter missed it.
 */
const requestText = String(req.originalRequest || req.rawText || '').toLowerCase();

const mentionedUserMatch = requestText.match(
  /\b(employee\d+|intern\d+|contractor\d+|mlab-admin|mlabadmin)(?:'s|s)?\b/i
);

const mentionedUser = mentionedUserMatch ? mentionedUserMatch[1] : '';

const monitoredUsers = Object.keys(perUserCounts);

const focusedUser = req.userFilter || mentionedUser || '';

const requestedUserExists =
  !focusedUser || monitoredUsers.includes(focusedUser);

const unknownRequestedUser =
  focusedUser && !requestedUserExists ? focusedUser : '';

let focusedUserData = null;

if (focusedUser && perUserCounts[focusedUser]) {
  focusedUserData = {
    user: focusedUser,
    ...perUserCounts[focusedUser],
    commands: userCommands[focusedUser]
  };
}

const compareUsers = Array.isArray(req.compareUsers) ? req.compareUsers : [];

const topRiskUsers = [...attentionUsers, ...warnings]
  .sort((a, b) => Number(b.count || 0) - Number(a.count || 0))
  .slice(0, 5);

return [{
  json: {
    mode: req.mode || 'chat',
    host: req.host || 'mlab-test',
    chatId: req.chatId || '6925837675',
    fromUser: req.fromUser || 'telegram-user',
    originalRequest: req.originalRequest || req.rawText || 'Security report request',
    rawText: req.rawText || req.originalRequest || '',
    timeframe: req.timeframe || 'today',
    requestType: req.requestType || 'general_report',
    userFilter: focusedUser,
    compareUsers,
    attentionThreshold: threshold,

    perUserCounts,
    violationSummary: perUserCounts,
    warnings,
    attentionUsers,
    totalPolicyViolations,
    userCommands,

    focusedUser,
    focusedUserData,
    monitoredUsers,
    requestedUserExists,
    unknownRequestedUser,

    topRiskUsers,

    alertNeeded: attentionUsers.length > 0,
    shouldAlertByRule: attentionUsers.length > 0,
    hasWarnings: warnings.length > 0,

    rawLineCount: lines.length,
    missingCollector: /script missing:/i.test(raw),
    stderr
  }
}];

