const raw = String($json.output || $json.text || $json.message || '').trim();

const cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```/, '')
  .replace(/```$/, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (!match) {
    throw new Error('AI Intent Agent did not return valid JSON. Raw output: ' + raw);
  }
  parsed = JSON.parse(match[0]);
}

const allowedTypes = [
  'general_report',
  'user_warnings',
  'attention_users',
  'explain_user',
  'compare_users',
  'normal_chat'
];

const requestType = allowedTypes.includes(parsed.requestType)
  ? parsed.requestType
  : 'normal_chat';

const isReportRequest = requestType !== 'normal_chat';

return [{
  json: {
    mode: 'chat',
    host: parsed.host || 'mlab-test',
    timeframe: parsed.timeframe || 'today',
    requestType,
    chatId: String(parsed.chatId || '6925837675'),
    fromUser: parsed.fromUser || 'telegram-user',
    originalRequest: parsed.originalRequest || parsed.rawText || '',
    rawText: parsed.rawText || parsed.originalRequest || '',
    userFilter: parsed.userFilter || '',
    compareUsers: Array.isArray(parsed.compareUsers) ? parsed.compareUsers : [],
    attentionThreshold: Number(parsed.attentionThreshold || 5),
    isReportRequest,
    confidence: Number(parsed.confidence || 0),
    rawAiIntent: raw
  }
}];
